const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    var canada = ee.FeatureCollection('FAO/GAUL/2015/level0')
        .filter(ee.Filter.eq('ADM0_NAME', 'Canada'));

    var dates2023 = ['2023-01-01', '2023-08-03'];
    var dates2025 = ['2025-01-01', '2025-08-03'];

    // 2. Data Acquisition - MCD64A1 Burned Area product
    var burnedArea = ee.ImageCollection('MODIS/061/MCD64A1')
        .select('BurnDate');

    var col2023 = burnedArea.filterDate(dates2023[0], dates2023[1])
        .filterBounds(canada);
    var col2025 = burnedArea.filterDate(dates2025[0], dates2025[1])
        .filterBounds(canada);

    // Check for empty collections
    var size2023 = col2023.size().getInfo();
    var size2025 = col2025.size().getInfo();

    console.log('2023 Images:', size2023);
    console.log('2025 Images:', size2025);

    if (size2023 === 0 || size2025 === 0) {
        console.log('<answer>C1</answer>');
        return;
    }

    // 3. Processing - Create burned area masks
    // BurnDate > 0 indicates burned pixel
    var burned2023 = col2023.map(function(img) {
        return img.gt(0).selfMask();
    }).sum().rename('burned');

    var burned2025 = col2025.map(function(img) {
        return img.gt(0).selfMask();
    }).sum().rename('burned');

    // 4. Calculate burned area (pixel count * area per pixel)
    // MCD64A1 has 500m resolution = 0.25 km² per pixel
    var pixelArea = 0.25; // km²

    var stats2023 = burned2023.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e12
    });

    var stats2025 = burned2025.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: canada,
        scale: 1000,
        maxPixels: 1e12
    });

    var burnedPixels2023 = stats2023.get('burned').getInfo();
    var burnedPixels2025 = stats2025.get('burned').getInfo();

    console.log('2023 Burned Pixels:', burnedPixels2023);
    console.log('2025 Burned Pixels:', burnedPixels2025);

    // Check for no valid pixels
    if (burnedPixels2023 === null || burnedPixels2025 === null ||
        burnedPixels2023 === undefined || burnedPixels2025 === undefined) {
        console.log('<answer>C3</answer>');
        return;
    }

    if (burnedPixels2023 === 0 && burnedPixels2025 === 0) {
        console.log('<answer>C2</answer>');
        return;
    }

    // 5. Calculate area in km²
    var area2023 = burnedPixels2023 * pixelArea;
    var area2025 = burnedPixels2025 * pixelArea;

    console.log('2023 Burned Area (km²):', Math.round(area2023));
    console.log('2025 Burned Area (km²):', Math.round(area2025));
    console.log('Ratio (2025/2023):', (area2025/area2023).toFixed(2));

    // 6. Validation & Final Answer
    // Check for invalid values
    if (isNaN(area2023) || isNaN(area2025) || 
        area2023 < 0 || area2025 < 0) {
        console.log('<answer>C3</answer>');
        return;
    }

    // Compare burned areas
    if (area2025 > area2023) {
        console.log('<answer>A</answer>');
    } else {
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
